import { useMemo, useState } from 'react';
import {
  Activity, AlertTriangle, ArrowRight, BarChart3, Bell, BrainCircuit, CalendarDays,
  Check, ChevronDown, ChevronRight, CircleDollarSign, ClipboardList, CloudSun,
  Coffee, Download, FileText, Leaf, LineChart as LineChartIcon, LogIn, Menu, MoreHorizontal,
  Package, PanelLeftClose, Plus, Printer, RefreshCw, Search, Settings, ShieldCheck,
  Sparkles, Trash2, TrendingDown, TrendingUp, Users, Utensils, X, Zap,
} from 'lucide-react';
import type { ReactNode, FormEvent } from 'react';
import type { DailyFoodData, MealType, PredictionResult, Role, SurplusFood, User } from '@/types';
import { getStoredUser, signInDemo, signOutDemo } from '@/lib/auth';
import { useDailyData, usePredictions, useSurplus } from '@/hooks/useData';
import { calculatePrediction } from '@/lib/prediction';
import { createDailyData, createPrediction, createSurplus, updateSurplusStatus } from '@/lib/data';
import { formatDate, formatDateShort, formatKg, mean, round, today, tomorrow } from '@/lib/utils';

const green = '#168653';
const meals: MealType[] = ['Breakfast', 'Lunch', 'Snacks', 'Dinner'];

type View = 'dashboard' | 'daily' | 'prediction' | 'waste' | 'surplus' | 'reports' | 'settings' | 'admin';

function Logo({ light = false }: { light?: boolean }) {
  return <div className="flex items-center gap-3"><div className={`flex h-10 w-10 items-center justify-center rounded-xl ${light ? 'bg-white/15 text-white' : 'bg-[#e1f5e7] text-[#168653]'}`}><Leaf size={21} strokeWidth={2.5} /></div><div><div className={`font-display text-[17px] font-bold tracking-tight ${light ? 'text-white' : 'text-[#173328]'}`}>SmartCanteen <span className={light ? 'text-[#a6ebbf]' : 'text-[#168653]'}>AI</span></div><div className={`text-[10px] font-medium tracking-[.16em] ${light ? 'text-white/60' : 'text-[#759084]'}`}>SUSTAINABLE INTELLIGENCE</div></div></div>;
}

function Toast({ message, onClose }: { message: string; onClose: () => void }) { return <div className="fixed bottom-5 right-5 z-50 flex max-w-sm items-center gap-3 rounded-xl bg-[#173328] px-4 py-3 text-sm font-medium text-white shadow-xl"><Check size={17} className="text-[#91e4ad]" />{message}<button onClick={onClose} className="ml-2 text-white/60 hover:text-white"><X size={15} /></button></div>; }

function Badge({ children, tone = 'gray' }: { children: ReactNode; tone?: 'green' | 'yellow' | 'red' | 'gray' }) { return <span className={`badge badge-${tone}`}>{children}</span>; }
function Card({ children, className = '', hover = false }: { children: ReactNode; className?: string; hover?: boolean }) { return <div className={`card ${hover ? 'card-hover' : ''} ${className}`}>{children}</div>; }
function SectionTitle({ eyebrow, title, description }: { eyebrow?: string; title: string; description?: string }) { return <div className="mb-7"><div className="mb-1 text-[11px] font-bold uppercase tracking-[.17em] text-[#5eaa78]">{eyebrow}</div><h1 className="font-display text-2xl font-bold tracking-tight text-[#173328] sm:text-3xl">{title}</h1>{description && <p className="mt-2 max-w-2xl text-sm leading-6 text-[#718279]">{description}</p>}</div>; }

function StatCard({ icon: Icon, label, value, change, positive = true, accent = 'green' }: { icon: typeof Activity; label: string; value: string; change: string; positive?: boolean; accent?: string }) { return <Card hover className="relative overflow-hidden p-5"><div className={`absolute -right-5 -top-8 h-24 w-24 rounded-full opacity-70 ${accent === 'yellow' ? 'bg-[#fff3cc]' : accent === 'blue' ? 'bg-[#e3f0fb]' : 'bg-[#e3f5e7]'}`} /><div className="relative flex items-start justify-between"><div><div className="mb-3 text-xs font-semibold text-[#77877e]">{label}</div><div className="font-display text-2xl font-bold text-[#173328]">{value}</div><div className={`mt-2 flex items-center gap-1 text-[11px] font-bold ${positive ? 'text-[#2c9960]' : 'text-[#d46b46]'}`}>{positive ? <TrendingDown size={13} /> : <TrendingUp size={13} />}{change}<span className="font-medium text-[#8b9b92]">vs last week</span></div></div><div className={`flex h-10 w-10 items-center justify-center rounded-xl ${accent === 'yellow' ? 'bg-[#fff4d7] text-[#c48e25]' : accent === 'blue' ? 'bg-[#e5f1fb] text-[#3987b9]' : 'bg-[#e2f5e7] text-[#168653]'}`}><Icon size={19} /></div></div></Card>; }

function MiniBars({ values, color = green, labels }: { values: number[]; color?: string; labels?: string[] }) { const max = Math.max(...values, 1); return <div className="flex h-36 items-end gap-2">{values.map((v, i) => <div key={i} className="group flex flex-1 flex-col items-center justify-end gap-1"><div className="relative w-full rounded-t-md bg-[#eaf3ed]" style={{ height: `${Math.max(8, v / max * 104)}px` }}><div className="absolute inset-0 rounded-t-md opacity-90 transition-all group-hover:opacity-100" style={{ background: color }} /></div>{labels && <span className="text-[10px] text-[#8a9990]">{labels[i]}</span>}</div>)}</div>; }
function LineChart({ values, labels, color = green }: { values: number[]; labels: string[]; color?: string }) { const max = Math.max(...values, 1); const min = Math.min(...values); const points = values.map((v, i) => `${(i / Math.max(values.length - 1, 1)) * 100},${96 - ((v - min) / Math.max(max - min, 1)) * 70}`).join(' '); return <div><div className="relative h-40"><svg viewBox="0 0 100 100" preserveAspectRatio="none" className="h-full w-full overflow-visible"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={color} stopOpacity=".18" /><stop offset="100%" stopColor={color} stopOpacity="0" /></linearGradient></defs><polygon points={`0,100 ${points} 100,100`} fill="url(#area)" /><polyline points={points} fill="none" stroke={color} strokeWidth="2" vectorEffect="non-scaling-stroke" strokeLinecap="round" strokeLinejoin="round" />{values.map((v, i) => <circle key={i} cx={`${(i / Math.max(values.length - 1, 1)) * 100}`} cy={`${96 - ((v - min) / Math.max(max - min, 1)) * 70}`} r="1.8" fill="white" stroke={color} strokeWidth="1.4" vectorEffect="non-scaling-stroke" />)}</svg></div><div className="mt-2 flex justify-between text-[10px] text-[#8a9990]">{labels.map((label) => <span key={label}>{label}</span>)}</div></div>; }
function ChartCard({ title, subtitle, children, action }: { title: string; subtitle?: string; children: ReactNode; action?: ReactNode }) { return <Card className="p-5"><div className="mb-5 flex items-start justify-between"><div><h3 className="font-display text-[15px] font-bold text-[#173328]">{title}</h3>{subtitle && <p className="mt-1 text-xs text-[#8a9990]">{subtitle}</p>}</div>{action ?? <button className="text-[#9aa9a1] hover:text-[#168653]"><MoreHorizontal size={18} /></button>}</div>{children}</Card>; }

function Landing({ onStart }: { onStart: () => void }) { const steps: Array<[string, string, typeof ClipboardList]> = [['01', 'Collect data', ClipboardList], ['02', 'Analyze with AI', BrainCircuit], ['03', 'Predict demand', LineChartIcon], ['04', 'Reduce waste', Leaf]]; return <div className="min-h-screen overflow-hidden bg-[#f7fbf8]"><header className="mx-auto flex max-w-7xl items-center justify-between px-5 py-5 lg:px-10"><Logo /><nav className="hidden items-center gap-8 text-sm font-semibold text-[#61736a] md:flex"><a href="#features" className="hover:text-[#168653]">Platform</a><a href="#how" className="hover:text-[#168653]">How it works</a><a href="#impact" className="hover:text-[#168653]">Impact</a></nav><button onClick={onStart} className="btn btn-primary px-5 py-2.5 text-sm">Sign in <ArrowRight size={15} /></button></header><main><section className="relative mx-auto grid max-w-7xl items-center gap-12 px-5 pb-16 pt-12 lg:grid-cols-[1.02fr_.98fr] lg:px-10 lg:pb-24 lg:pt-20"><div className="absolute -left-40 -top-40 h-96 w-96 rounded-full bg-[#d8f1df] blur-3xl" /><div className="relative"><div className="mb-5 inline-flex items-center gap-2 rounded-full border border-[#c9e7d2] bg-white px-3 py-1.5 text-xs font-bold text-[#2f9160]"><Sparkles size={13} /> Smarter canteens, lighter footprint</div><h1 className="max-w-xl font-display text-5xl font-bold leading-[1.04] tracking-[-.045em] text-[#173328] sm:text-6xl">Predict food.<br /><span className="text-[#168653]">Prevent waste.</span></h1><p className="mt-6 max-w-lg text-base leading-7 text-[#6d7e75]">An AI-powered platform that helps college canteens predict food demand, reduce leftovers and make smarter preparation decisions.</p><div className="mt-8 flex flex-wrap gap-3"><button onClick={onStart} className="btn btn-primary">Get started <ArrowRight size={16} /></button><button onClick={onStart} className="btn btn-secondary">View dashboard <BarChart3 size={16} /></button></div><div className="mt-10 flex items-center gap-5"><div className="flex -space-x-2"><div className="flex h-8 w-8 items-center justify-center rounded-full border-2 border-white bg-[#b8e4c5] text-xs font-bold text-[#276b44]">SC</div><div className="flex h-8 w-8 items-center justify-center rounded-full border-2 border-white bg-[#f6d9ae] text-xs font-bold text-[#936633]">RK</div><div className="flex h-8 w-8 items-center justify-center rounded-full border-2 border-white bg-[#cbd9ef] text-xs font-bold text-[#41608f]">JM</div></div><p className="text-xs text-[#718279]"><b className="text-[#314b3d]">24+ campuses</b> already reducing waste</p></div></div><div className="relative"><div className="absolute -inset-5 rounded-[36px] bg-gradient-to-br from-[#dbf2e1] to-transparent blur-2xl" /><div className="relative rounded-[28px] border border-[#d7e9dc] bg-white p-4 shadow-[0_28px_80px_rgba(42,100,62,.12)]"><div className="rounded-[20px] bg-[#f4faf5] p-5"><div className="mb-5 flex items-center justify-between"><div><div className="text-[10px] font-bold uppercase tracking-[.15em] text-[#79a287]">Live canteen pulse</div><div className="mt-1 font-display text-lg font-bold text-[#173328]">Today's overview</div></div><div className="rounded-lg bg-white px-2.5 py-1.5 text-[11px] font-bold text-[#4d7760] shadow-sm">Tue, Oct 24</div></div><div className="grid grid-cols-3 gap-3"><div className="rounded-xl bg-white p-3"><Users size={15} className="text-[#56a875]" /><div className="mt-3 text-xl font-bold text-[#173328]">750</div><div className="text-[10px] text-[#84948b]">Present today</div></div><div className="rounded-xl bg-white p-3"><Utensils size={15} className="text-[#56a875]" /><div className="mt-3 text-xl font-bold text-[#173328]">620</div><div className="text-[10px] text-[#84948b]">Meals consumed</div></div><div className="rounded-xl bg-white p-3"><Trash2 size={15} className="text-[#e4945e]" /><div className="mt-3 text-xl font-bold text-[#173328]">8.4<span className="text-sm">kg</span></div><div className="text-[10px] text-[#84948b]">Food waste</div></div></div><div className="mt-4 rounded-xl bg-white p-4"><div className="flex items-center justify-between"><span className="text-xs font-bold text-[#355343]">Meals prepared vs consumed</span><span className="badge badge-green">12% less waste</span></div><div className="mt-4"><MiniBars values={[72, 82, 68, 90, 78, 84, 80]} labels={['M','T','W','T','F','S','S']} /></div></div><div className="mt-4 flex items-center gap-3 rounded-xl bg-[#173328] p-4 text-white"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#2f9b61]"><BrainCircuit size={18} /></div><div><div className="text-[10px] font-bold uppercase tracking-[.12em] text-[#a7dfb9]">AI insight</div><div className="mt-0.5 text-xs text-white/80">Demand is trending 8% lower tomorrow</div></div><ChevronRight size={16} className="ml-auto text-white/50" /></div></div></div></div></section><section id="features" className="border-y border-[#e6efe8] bg-white py-16"><div className="mx-auto max-w-7xl px-5 lg:px-10"><div className="mb-10 max-w-xl"><div className="mb-2 text-xs font-bold uppercase tracking-[.16em] text-[#5eaa78]">One platform, measurable impact</div><h2 className="font-display text-3xl font-bold tracking-tight text-[#173328]">A smarter way to run your canteen</h2></div><div className="grid gap-5 md:grid-cols-3"><Feature icon={BrainCircuit} title="AI demand prediction" text="Predict tomorrow's food requirement using historical consumption, attendance and day-of-week patterns." /><Feature icon={TrendingDown} title="Waste monitoring" text="Spot unusual waste patterns early and turn every leftover into a measurable learning signal." /><Feature icon={Package} title="Smart redistribution" text="Coordinate surplus food with authorized volunteers while keeping safety rules front and center." /></div></div></section><section id="how" className="mx-auto max-w-7xl px-5 py-16 lg:px-10"><div className="text-center"><div className="mb-2 text-xs font-bold uppercase tracking-[.16em] text-[#5eaa78]">Simple by design</div><h2 className="font-display text-3xl font-bold tracking-tight text-[#173328]">From data to impact in four steps</h2></div><div className="relative mt-12 grid gap-8 md:grid-cols-4">{steps.map(([number, title, Icon]) => <div key={String(number)} className="relative text-center"><div className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-[#e4f5e8] text-[#168653]"><Icon size={23 as number} /></div><div className="mt-4 text-sm font-bold text-[#173328]">{number} / {String(title)}</div>{number !== '04' && <div className="absolute left-[65%] top-7 hidden w-2/3 border-t border-dashed border-[#b9d9c2] md:block" />}</div>)}</div></section><section id="impact" className="bg-[#173328] py-14 text-white"><div className="mx-auto grid max-w-7xl gap-8 px-5 sm:grid-cols-2 lg:grid-cols-4 lg:px-10">{[['18,420','Meals optimized'],['32%','Food waste reduced'],['$14.8k','Estimated savings'],['126','Days analyzed']].map(([value, label]) => <div key={label} className="text-center"><div className="font-display text-3xl font-bold text-[#a7e8b9]">{value}</div><div className="mt-2 text-xs font-medium text-white/55">{label}</div></div>)}</div></section></main><footer className="mx-auto flex max-w-7xl flex-col justify-between gap-4 px-5 py-7 text-xs text-[#809087] sm:flex-row lg:px-10"><Logo /><span>Built for campuses that care about tomorrow.</span></footer></div>; }
function Feature({ icon: Icon, title, text }: { icon: typeof BrainCircuit; title: string; text: string }) { return <Card hover className="p-6"><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-[#e7f5ea] text-[#168653]"><Icon size={20} /></div><h3 className="mt-5 font-display font-bold text-[#173328]">{title}</h3><p className="mt-2 text-sm leading-6 text-[#75867d]">{text}</p><div className="mt-5 flex items-center gap-1 text-xs font-bold text-[#168653]">Explore feature <ArrowRight size={13} /></div></Card>; }

function Login({ onLogin, onBack }: { onLogin: (user: User) => void; onBack: () => void }) { const [role, setRole] = useState<Role>('staff'); const [loading, setLoading] = useState(false); const [error, setError] = useState(''); async function submit(e: FormEvent) { e.preventDefault(); setLoading(true); setError(''); try { onLogin(await signInDemo(role)); } catch { setError('We could not connect to the demo account. Please try again.'); } finally { setLoading(false); } } return <div className="flex min-h-screen items-center justify-center bg-[#f4faf5] px-5 py-10"><div className="w-full max-w-md"><div className="mb-8 text-center"><div className="mb-7 inline-block"><Logo /></div><h1 className="font-display text-2xl font-bold text-[#173328]">Welcome back</h1><p className="mt-2 text-sm text-[#788981]">Choose your workspace to continue</p></div><Card className="p-7"><form onSubmit={submit}><label className="label">Sign in as</label><div className="mb-6 grid grid-cols-2 gap-3">{(['staff','admin'] as Role[]).map((item) => <button type="button" key={item} onClick={() => setRole(item)} className={`rounded-xl border p-4 text-left transition ${role === item ? 'border-[#65ba82] bg-[#eef9f0]' : 'border-[#e1ebe3] bg-white hover:border-[#b7d9c1]'}`}><div className={`mb-3 flex h-8 w-8 items-center justify-center rounded-lg ${role === item ? 'bg-[#ccefd5] text-[#168653]' : 'bg-[#f0f3f1] text-[#72837a]'}`}>{item === 'admin' ? <ShieldCheck size={17} /> : <Utensils size={17} />}</div><div className="text-sm font-bold capitalize text-[#294536]">{item === 'staff' ? 'Canteen Staff' : 'Administrator'}</div><div className="mt-1 text-[11px] text-[#84948b]">Demo access</div></button>)}</div>{error && <div className="mb-4 rounded-lg bg-[#fff0ee] px-3 py-2 text-xs font-medium text-[#af4e46]">{error}</div>}<button disabled={loading} className="btn btn-primary w-full">{loading ? <RefreshCw size={16} className="animate-spin" /> : <LogIn size={16} />} {loading ? 'Signing in…' : 'Continue to workspace'}</button></form><div className="mt-5 flex items-center justify-center gap-2 text-[11px] text-[#96a29c]"><ShieldCheck size={13} /> Secure demo environment</div></Card><button onClick={onBack} className="mx-auto mt-6 flex items-center gap-1 text-xs font-semibold text-[#6e8478] hover:text-[#168653]"><ArrowRight size={13} className="rotate-180" /> Back to home</button></div></div>; }

function Shell({ user, view, onView, onLogout, children }: { user: User; view: View; onView: (view: View) => void; onLogout: () => void; children: ReactNode }) { const [open, setOpen] = useState(false); const nav = [{ id: 'dashboard' as View, label: 'Dashboard', icon: BarChart3 }, { id: 'daily' as View, label: 'Daily data', icon: ClipboardList }, { id: 'prediction' as View, label: 'AI prediction', icon: BrainCircuit }, { id: 'waste' as View, label: 'Waste monitoring', icon: Trash2 }, { id: 'surplus' as View, label: 'Surplus food', icon: Package }, { id: 'reports' as View, label: 'Reports', icon: FileText }]; return <div className="flex min-h-screen bg-[#f5f8f6]"><aside className={`fixed inset-y-0 left-0 z-40 flex w-[250px] flex-col bg-[#173328] px-4 py-5 transition-transform lg:static lg:translate-x-0 ${open ? 'translate-x-0' : '-translate-x-full'}`}><div className="px-3"><Logo light /></div><div className="mt-12 flex-1"><div className="mb-3 px-3 text-[10px] font-bold uppercase tracking-[.17em] text-white/35">Workspace</div><nav className="space-y-1">{nav.map(({ id, label, icon: Icon }) => <button key={id} onClick={() => { onView(id); setOpen(false); }} className={`flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-semibold transition ${view === id ? 'bg-[#2d7650] text-white' : 'text-white/55 hover:bg-white/7 hover:text-white'}`}><Icon size={17} />{label}{id === 'prediction' && <span className="ml-auto rounded-md bg-[#8bd99e] px-1.5 py-0.5 text-[9px] font-bold text-[#173328]">NEW</span>}</button>)}</nav>{user.role === 'admin' && <><div className="mb-3 mt-9 px-3 text-[10px] font-bold uppercase tracking-[.17em] text-white/35">Management</div><button onClick={() => { onView('admin'); setOpen(false); }} className={`flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-semibold ${view === 'admin' ? 'bg-[#2d7650] text-white' : 'text-white/55 hover:bg-white/7 hover:text-white'}`}><ShieldCheck size={17} />Admin overview</button></>}</div><div className="border-t border-white/10 pt-4"><button onClick={() => onView('settings')} className={`flex w-full items-center gap-3 rounded-xl px-3 py-3 text-sm font-semibold ${view === 'settings' ? 'bg-[#2d7650] text-white' : 'text-white/55 hover:text-white'}`}><Settings size={17} />Settings</button><div className="mt-4 flex items-center gap-3 rounded-xl bg-white/7 p-3"><div className="flex h-8 w-8 items-center justify-center rounded-full bg-[#afdcbc] text-xs font-bold text-[#25643e]">{user.name.split(' ').map((part) => part[0]).join('')}</div><div className="min-w-0 flex-1"><div className="truncate text-xs font-bold text-white">{user.name}</div><div className="text-[10px] capitalize text-white/45">{user.role} account</div></div><button onClick={onLogout} className="text-white/35 hover:text-white" title="Sign out"><LogIn size={15} className="rotate-180" /></button></div></div></aside>{open && <button className="fixed inset-0 z-30 bg-[#173328]/30 lg:hidden" onClick={() => setOpen(false)} aria-label="Close menu" />}<main className="min-w-0 flex-1"><header className="sticky top-0 z-20 flex h-[76px] items-center justify-between border-b border-[#e5ece7] bg-[#f5f8f6]/90 px-5 backdrop-blur lg:px-9"><div className="flex items-center gap-3"><button onClick={() => setOpen(true)} className="rounded-lg p-2 text-[#60736a] hover:bg-white lg:hidden"><Menu size={20} /></button><div className="hidden items-center gap-2 text-xs text-[#819087] sm:flex"><span>Workspace</span><ChevronRight size={13} /><span className="font-semibold capitalize text-[#304c3c]">{view === 'admin' ? 'Admin overview' : view}</span></div><div className="sm:hidden"><Logo /></div></div><div className="flex items-center gap-2"><button className="hidden items-center gap-2 rounded-xl border border-[#e2ebe4] bg-white px-3 py-2 text-xs text-[#9aa79f] sm:flex"><Search size={15} /> Search <span className="ml-5 rounded bg-[#f1f4f2] px-1.5 py-0.5 text-[10px]">⌘ K</span></button><button className="relative rounded-xl p-2.5 text-[#718279] hover:bg-white"><Bell size={18} /><span className="absolute right-2 top-2 h-1.5 w-1.5 rounded-full bg-[#e66e52]" /></button><div className="ml-1 hidden h-8 w-px bg-[#dee8e0] sm:block" /><div className="hidden items-center gap-2 pl-2 sm:flex"><div className="flex h-8 w-8 items-center justify-center rounded-full bg-[#afdcbc] text-xs font-bold text-[#25643e]">{user.name.split(' ').map((part) => part[0]).join('')}</div><ChevronDown size={14} className="text-[#829189]" /></div></div></header><div className="mx-auto max-w-[1440px] p-5 lg:p-9">{children}</div></main></div>; }

function Dashboard({ data, onView }: { data: DailyFoodData[]; onView: (v: View) => void }) { const todayData = data.filter((r) => r.date === data[0]?.date); const attendance = Math.round(mean(todayData.map((r) => r.students_present)) || 750); const prepared = todayData.reduce((s, r) => s + r.meals_prepared, 0) || 700; const consumed = todayData.reduce((s, r) => s + r.meals_consumed, 0) || 620; const waste = todayData.reduce((s, r) => s + Number(r.leftover_kg), 0) || 8.4; const recent = data.slice(0, 28); const byDate = Array.from(new Set(recent.map((r) => r.date))).slice(0, 7).reverse(); const wasteValues = byDate.map((date) => round(recent.filter((r) => r.date === date).reduce((s, r) => s + Number(r.leftover_kg), 0), 1)); return <><div className="mb-8 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><div className="mb-2 flex items-center gap-2 text-xs font-semibold text-[#789086]"><CloudSun size={15} className="text-[#e4a65e]" /> Tuesday, October 24, 2024</div><h1 className="font-display text-2xl font-bold text-[#173328] sm:text-3xl">Good morning, Sarah <span className="text-[#e8a66e]">.</span></h1><p className="mt-2 text-sm text-[#7c8c83]">Here's the pulse of your canteen today.</p></div><button onClick={() => onView('daily')} className="btn btn-primary"><Plus size={16} /> Add daily data</button></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard icon={Users} label="Today's attendance" value={`${attendance.toLocaleString()} students`} change="6.2%" /><StatCard icon={Utensils} label="Meals prepared" value={prepared.toLocaleString()} change="2.4%" positive={false} accent="blue" /><StatCard icon={Coffee} label="Meals consumed" value={consumed.toLocaleString()} change="8.1%" accent="yellow" /><StatCard icon={Trash2} label="Food waste" value={formatKg(waste)} change="12.8%" accent="yellow" /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.35fr_1fr]"><ChartCard title="Meals prepared vs consumed" subtitle="Last 7 days" action={<button className="btn btn-ghost px-2 py-1 text-xs">Last 7 days <ChevronDown size={13} /></button>}><div className="mb-3 flex gap-4 text-[11px] text-[#7e8f85]"><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-[#168653]" />Prepared</span><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-[#a9dcb7]" />Consumed</span></div><MiniBars values={[680,720,650,760,710,690,700]} labels={['Oct 18','19','20','21','22','23','24']} /></ChartCard><ChartCard title="Daily food waste trend" subtitle="Kilograms, last 7 days"><LineChart values={wasteValues.length ? wasteValues : [8,11,9,12,10,9,8]} labels={byDate.map((d) => formatDateShort(d))} /></ChartCard></div><div className="mt-5 grid gap-5 lg:grid-cols-[1fr_1.2fr]"><Card className="overflow-hidden bg-[#173328] p-6 text-white"><div className="flex items-start justify-between"><div><div className="mb-3 flex items-center gap-2 text-[11px] font-bold uppercase tracking-[.14em] text-[#9ce4b1]"><BrainCircuit size={15} /> AI insight</div><h3 className="max-w-sm font-display text-xl font-bold leading-snug">Consumption is <span className="text-[#9ce4b1]">11% lower</span> than your weekly average.</h3><p className="mt-3 max-w-sm text-sm leading-6 text-white/60">Consider reducing tomorrow's preparation quantity by around 45 meals to keep waste low.</p></div><div className="rounded-2xl bg-white/10 p-3"><Zap size={22} className="text-[#f3c96f]" /></div></div><button onClick={() => onView('prediction')} className="mt-6 flex items-center gap-2 text-xs font-bold text-[#a6e8b8] hover:text-white">View AI prediction <ArrowRight size={14} /></button></Card><ChartCard title="Weekly performance" subtitle="Your sustainability snapshot"><div className="grid grid-cols-3 gap-4"><div><div className="text-xs text-[#85968d]">Waste reduced</div><div className="mt-2 font-display text-2xl font-bold text-[#168653]">18.4%</div><div className="mt-1 text-[11px] text-[#789086]">vs last month</div></div><div><div className="text-xs text-[#85968d]">Meals saved</div><div className="mt-2 font-display text-2xl font-bold text-[#173328]">1,248</div><div className="mt-1 text-[11px] text-[#789086]">this month</div></div><div><div className="text-xs text-[#85968d]">Savings</div><div className="mt-2 font-display text-2xl font-bold text-[#173328]">$2.4k</div><div className="mt-1 text-[11px] text-[#789086]">estimated</div></div></div><div className="mt-7 h-2 overflow-hidden rounded-full bg-[#e8f0ea]"><div className="h-full w-[72%] rounded-full bg-[#52b878]" /></div><div className="mt-2 flex justify-between text-[10px] text-[#899890]"><span>Goal progress</span><span>72% of monthly goal</span></div></ChartCard></div></>; }

function DailyPage({ data, onSaved, toast }: { data: DailyFoodData[]; onSaved: () => void; toast: (message: string) => void }) { const [form, setForm] = useState({ date: today(), students_present: '750', meals_prepared: '700', meals_consumed: '620', leftover_kg: '8.4', meal_type: 'Lunch' as MealType, notes: '' }); const [saving, setSaving] = useState(false); const [error, setError] = useState(''); async function submit(e: FormEvent) { e.preventDefault(); const nums = ['students_present','meals_prepared','meals_consumed','leftover_kg'] as const; if (nums.some((key) => Number(form[key]) < 0) || Number(form.meals_consumed) > Number(form.meals_prepared)) { setError('Please check the numbers. Consumed meals cannot exceed prepared meals.'); return; } setSaving(true); setError(''); try { await createDailyData({ date: form.date, students_present: Number(form.students_present), meals_prepared: Number(form.meals_prepared), meals_consumed: Number(form.meals_consumed), leftover_kg: Number(form.leftover_kg), meal_type: form.meal_type, notes: form.notes || null }); toast('Daily canteen data saved successfully'); onSaved(); } catch { setError('Could not save this entry. Please try again.'); } finally { setSaving(false); } } const recent = data.slice(0, 10); return <><SectionTitle eyebrow="Data collection" title="Daily food data" description="Capture attendance and consumption details to keep your AI recommendations accurate." /><div className="grid gap-5 xl:grid-cols-[.95fr_1.35fr]"><Card className="p-6"><div className="mb-5 flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#e4f5e8] text-[#168653]"><ClipboardList size={19} /></div><div><h3 className="font-display font-bold text-[#173328]">Add a daily entry</h3><p className="text-xs text-[#819087]">One entry per meal service</p></div></div><form onSubmit={submit} className="space-y-4"><div><label className="label">Date</label><input required type="date" className="input" value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} /></div><div className="grid grid-cols-2 gap-3"><div><label className="label">Students present</label><input required min="0" type="number" className="input" value={form.students_present} onChange={(e) => setForm({ ...form, students_present: e.target.value })} /></div><div><label className="label">Meal type</label><select className="input" value={form.meal_type} onChange={(e) => setForm({ ...form, meal_type: e.target.value as MealType })}>{meals.map((meal) => <option key={meal}>{meal}</option>)}</select></div></div><div className="grid grid-cols-2 gap-3"><div><label className="label">Meals prepared</label><input required min="0" type="number" className="input" value={form.meals_prepared} onChange={(e) => setForm({ ...form, meals_prepared: e.target.value })} /></div><div><label className="label">Meals consumed</label><input required min="0" type="number" className="input" value={form.meals_consumed} onChange={(e) => setForm({ ...form, meals_consumed: e.target.value })} /></div></div><div><label className="label">Leftover food <span className="font-normal text-[#91a098]">(kg)</span></label><input required min="0" step="0.1" type="number" className="input" value={form.leftover_kg} onChange={(e) => setForm({ ...form, leftover_kg: e.target.value })} /></div><div><label className="label">Notes <span className="font-normal text-[#91a098]">(optional)</span></label><textarea rows={3} className="input resize-none" placeholder="Special menu, weather, events…" value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })} /></div>{error && <div className="rounded-lg bg-[#fff0ee] px-3 py-2 text-xs font-medium text-[#af4e46]">{error}</div>}<button disabled={saving} className="btn btn-primary w-full">{saving ? <RefreshCw size={16} className="animate-spin" /> : <Check size={16} />}{saving ? 'Saving…' : 'Save daily data'}</button></form></Card><Card className="overflow-hidden"><div className="flex items-center justify-between border-b border-[#e6eee8] p-5"><div><h3 className="font-display font-bold text-[#173328]">Recent entries</h3><p className="mt-1 text-xs text-[#819087]">Your latest canteen activity</p></div><button className="btn btn-ghost px-2 py-1 text-xs"><Download size={14} /> Export</button></div><div className="overflow-x-auto"><table className="w-full text-left text-xs"><thead className="bg-[#f8fbf9] text-[10px] uppercase tracking-wider text-[#85968d]"><tr><th className="px-5 py-3 font-bold">Date</th><th className="px-4 py-3 font-bold">Students</th><th className="px-4 py-3 font-bold">Prepared</th><th className="px-4 py-3 font-bold">Consumed</th><th className="px-4 py-3 font-bold">Waste</th><th className="px-5 py-3 font-bold">Type</th></tr></thead><tbody className="divide-y divide-[#edf2ee]">{recent.map((row) => <tr key={row.id} className="text-[#50665a] hover:bg-[#fbfdfb]"><td className="whitespace-nowrap px-5 py-3.5 font-semibold text-[#344e3f]">{formatDate(row.date)}</td><td className="px-4 py-3.5">{row.students_present}</td><td className="px-4 py-3.5">{row.meals_prepared}</td><td className="px-4 py-3.5">{row.meals_consumed}</td><td className="px-4 py-3.5 font-semibold text-[#d17b4e]">{row.leftover_kg} kg</td><td className="px-5 py-3.5"><Badge tone="green">{row.meal_type}</Badge></td></tr>)}</tbody></table></div></Card></div></>; }

function PredictionPage({ data, toast }: { data: DailyFoodData[]; toast: (message: string) => void }) { const [form, setForm] = useState({ date: tomorrow(), students: '780', meal: 'Lunch' as MealType }); const [result, setResult] = useState<PredictionResult | null>(null); const [saving, setSaving] = useState(false); function run(e: FormEvent) { e.preventDefault(); setResult(calculatePrediction(data, { date: form.date, expectedStudents: Number(form.students), mealType: form.meal })); } async function save() { if (!result) return; setSaving(true); try { await createPrediction({ prediction_date: form.date, meal_type: form.meal, expected_students: result.expectedStudents, predicted_meals: result.predictedMeals, recommended_preparation: result.recommendedPreparation, expected_waste: result.expectedWaste, confidence: result.confidence, actual_consumed: null }); toast('Prediction saved to your history'); } catch { toast('Prediction created, but history could not be saved'); } finally { setSaving(false); } } const compare = result ? [result.historicalAverage, result.predictedMeals, Math.round(result.predictedMeals * .97)] : [580,635,620]; return <><SectionTitle eyebrow="Decision intelligence" title="AI food demand prediction" description="Turn your historical canteen patterns into a practical preparation plan for tomorrow." /><div className="grid gap-5 xl:grid-cols-[.75fr_1.25fr]"><Card className="p-6"><div className="mb-5 flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#e4f5e8] text-[#168653]"><BrainCircuit size={20} /></div><div><h3 className="font-display font-bold text-[#173328]">Set prediction inputs</h3><p className="text-xs text-[#819087]">The model learns from {data.length} historical records</p></div></div><form onSubmit={run} className="space-y-4"><div><label className="label">Prediction date</label><input type="date" required className="input" value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} /></div><div><label className="label">Expected student attendance</label><div className="relative"><Users size={16} className="absolute left-3 top-3.5 text-[#8ba096]" /><input type="number" min="0" required className="input pl-9" value={form.students} onChange={(e) => setForm({ ...form, students: e.target.value })} /></div></div><div><label className="label">Meal type</label><select className="input" value={form.meal} onChange={(e) => setForm({ ...form, meal: e.target.value as MealType })}>{meals.map((meal) => <option key={meal}>{meal}</option>)}</select></div><button className="btn btn-primary mt-2 w-full"><Zap size={16} /> Predict demand</button></form><div className="mt-5 rounded-xl bg-[#f4faf5] p-4"><div className="flex gap-2"><Activity size={15} className="mt-0.5 text-[#168653]" /><p className="text-xs leading-5 text-[#708178]">Uses weighted recent averages, day-of-week matching, attendance ratios and historical waste patterns. Results improve as you add data.</p></div></div></Card><div className="space-y-5"><Card className="overflow-hidden bg-[#173328] p-6 text-white"><div className="flex items-start justify-between"><div><div className="flex items-center gap-2 text-[11px] font-bold uppercase tracking-[.14em] text-[#a4e6b5]"><Sparkles size={14} /> Recommendation</div><h2 className="mt-4 max-w-lg font-display text-2xl font-bold leading-tight">{result ? <>Prepare approximately <span className="text-[#a4e6b5]">{result.recommendedPreparation} meals</span> for {form.meal.toLowerCase()}.</> : 'Run a prediction to see your preparation recommendation.'}</h2><p className="mt-3 text-sm text-white/55">{result ? `${result.confidence}% confidence · ${result.method === 'weighted_average' ? 'Weighted historical model' : 'Preliminary model'}` : 'The model will compare historical patterns with expected attendance.'}</p></div><div className="hidden rounded-2xl bg-white/10 p-4 sm:block"><BrainCircuit size={30} className="text-[#a4e6b5]" /></div></div><div className="mt-7 grid grid-cols-2 gap-3 sm:grid-cols-4"><Metric label="Expected students" value={result?.expectedStudents ?? '—'} /><Metric label="Predicted meals" value={result?.predictedMeals ?? '—'} /><Metric label="Expected waste" value={result ? `${result.expectedWaste}kg` : '—'} /><Metric label="Confidence" value={result ? `${result.confidence}%` : '—'} /></div></Card><ChartCard title="Prediction comparison" subtitle="Historical average vs AI prediction vs expected actual"><div className="flex gap-4 text-[11px] text-[#7e8f85]"><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-[#a9dcb7]" />Historical avg.</span><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-[#168653]" />AI prediction</span><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-[#f0c36b]" />Expected actual</span></div><div className="mt-5"><MiniBars values={compare} color={green} labels={['Historical avg.','AI prediction','Expected actual']} /></div></ChartCard>{result && <Card className="p-5"><div className="mb-3 text-xs font-bold uppercase tracking-[.12em] text-[#6a8977]">Model signals</div><div className="space-y-2">{result.factors.map((factor) => <div key={factor} className="flex items-center gap-2 text-xs text-[#718279]"><Check size={14} className="text-[#2b9a5d]" />{factor}</div>)}</div><button disabled={saving} onClick={save} className="btn btn-secondary mt-5 w-full">{saving ? 'Saving…' : 'Save prediction to history'}</button></Card>}</div></div></>; }
function Metric({ label, value }: { label: string; value: string | number }) { return <div className="rounded-xl bg-white/10 p-3"><div className="text-[10px] text-white/50">{label}</div><div className="mt-1 font-display text-xl font-bold text-white">{value}</div></div>; }

function WastePage({ data }: { data: DailyFoodData[] }) { const totalWaste = data.reduce((s, r) => s + Number(r.leftover_kg), 0); const avgWaste = mean(data.map((r) => Number(r.leftover_kg))); const highest = data.reduce((a, b) => Number(a.leftover_kg) > Number(b.leftover_kg) ? a : b, data[0]); const byMeal = meals.map((meal) => ({ meal, value: data.filter((r) => r.meal_type === meal).reduce((s, r) => s + Number(r.leftover_kg), 0) })); const recent = data.slice(0, 28); const dates = Array.from(new Set(recent.map((r) => r.date))).slice(0, 7).reverse(); const values = dates.map((date) => round(recent.filter((r) => r.date === date).reduce((s, r) => s + Number(r.leftover_kg), 0), 1)); const todayWaste = values[values.length - 1] || 8.4; const recentAvg = mean(values.slice(0, -1)) || 9; const high = todayWaste > recentAvg * 1.25; return <><SectionTitle eyebrow="Sustainability analytics" title="Waste monitoring" description="Understand where waste happens and act before it becomes tomorrow's problem." />{high && <div className="mb-5 flex items-start gap-3 rounded-2xl border border-[#f2d88c] bg-[#fff9e8] p-4"><div className="rounded-xl bg-[#ffedb7] p-2 text-[#c58d22]"><AlertTriangle size={19} /></div><div><div className="text-sm font-bold text-[#805d1e]">High waste alert</div><p className="mt-1 text-xs leading-5 text-[#9a7738]">Today's food waste is {Math.round((todayWaste / recentAvg - 1) * 100)}% higher than the recent average. Possible reason: attendance was lower than expected.</p></div></div>}<div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard icon={Trash2} label="Total food waste" value={`${round(totalWaste, 1)} kg`} change="18.4%" /><StatCard icon={Activity} label="Average daily waste" value={`${round(avgWaste, 1)} kg`} change="6.2%" accent="yellow" /><StatCard icon={TrendingUp} label="Highest waste day" value={highest ? `${round(Number(highest.leftover_kg),1)} kg` : '—'} change={highest ? formatDateShort(highest.date) : '—'} positive={false} accent="yellow" /><StatCard icon={TrendingDown} label="Waste reduction" value="18.4%" change="vs last month" /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.3fr_.7fr]"><ChartCard title="Daily waste trend" subtitle="Last 7 days"><LineChart values={values.length ? values : [9,10,8,12,9,11,8]} labels={dates.map((d) => formatDateShort(d))} color="#e39a56" /></ChartCard><ChartCard title="Waste by meal type" subtitle="Total kilograms"><div className="space-y-4">{byMeal.map(({ meal, value }) => <div key={meal}><div className="mb-1.5 flex justify-between text-xs"><span className="font-semibold text-[#4d6558]">{meal}</span><span className="font-bold text-[#d17b4e]">{round(value, 1)} kg</span></div><div className="h-2 overflow-hidden rounded-full bg-[#f2eee6]"><div className="h-full rounded-full bg-[#e5a35d]" style={{ width: `${Math.min(100, value / Math.max(...byMeal.map((m) => m.value), 1) * 100)}%` }} /></div></div>)}</div></ChartCard></div><div className="mt-5 grid gap-5 lg:grid-cols-2"><ChartCard title="Prepared vs consumed" subtitle="Today across all meal services"><div className="flex items-center justify-center py-4"><div className="relative flex h-40 w-40 items-center justify-center rounded-full" style={{ background: `conic-gradient(#168653 0 89%, #e6f1e8 89% 100%)` }}><div className="flex h-28 w-28 flex-col items-center justify-center rounded-full bg-white"><span className="font-display text-2xl font-bold text-[#173328]">89%</span><span className="text-[10px] text-[#84948b]">consumed</span></div></div></div><div className="mt-2 flex justify-center gap-5 text-[11px] text-[#7e8f85]"><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-[#168653]" />Consumed</span><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-[#e6f1e8]" />Remaining</span></div></ChartCard><Card className="p-6"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#e4f5e8] text-[#168653]"><Leaf size={19} /></div><div><h3 className="font-display font-bold text-[#173328]">What might be driving waste?</h3><p className="text-xs text-[#85958c]">Patterns detected in your data</p></div></div><div className="mt-6 space-y-4">{[['Low attendance days','Waste increases when attendance drops 15%+','61%'],['Over-preparation','Preparation buffer is above the 8% target','42%'],['Friday lunch','Friday lunch consumption trends lower','28%']].map(([title, desc, score]) => <div key={title} className="flex items-center gap-3"><div className="h-2 w-2 rounded-full bg-[#e2a15c]" /><div className="flex-1"><div className="text-xs font-bold text-[#3e584a]">{title}</div><div className="mt-1 text-[11px] text-[#88988f]">{desc}</div></div><span className="text-xs font-bold text-[#c58448]">{score}</span></div>)}</div></Card></div></>; }

function SurplusPage({ data, onRefresh, toast }: { data: SurplusFood[]; onRefresh: () => void; toast: (message: string) => void }) { const [form, setForm] = useState({ food_type: 'Veg Biryani', portions: '35', available_time: '1:00 PM - 2:00 PM', location: 'Main Canteen - Counter 3', contact_info: 'staff@smartcanteen.ai' }); const [show, setShow] = useState(false); const [saving, setSaving] = useState(false); async function submit(e: FormEvent) { e.preventDefault(); setSaving(true); try { await createSurplus({ ...form, portions: Number(form.portions), status: 'Available' }); setShow(false); toast('Surplus alert created and volunteers notified'); onRefresh(); } catch { toast('Could not create the surplus alert'); } finally { setSaving(false); } } async function update(id: string, status: SurplusFood['status']) { try { await updateSurplusStatus(id, status); toast(`Marked as ${status.toLowerCase()}`); onRefresh(); } catch { toast('Could not update this alert'); } } return <><div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><SectionTitle eyebrow="Circular campus" title="Surplus food" description="Coordinate safe, timely redistribution with authorized campus volunteers." /><button onClick={() => setShow(true)} className="btn btn-primary"><Plus size={16} /> Create surplus alert</button></div><Card className="mb-5 overflow-hidden bg-[#173328] p-6 text-white sm:p-7"><div className="flex flex-col justify-between gap-6 sm:flex-row sm:items-center"><div><div className="mb-2 flex items-center gap-2 text-[11px] font-bold uppercase tracking-[.15em] text-[#a6e7b6]"><Bell size={14} /> Volunteer coordination</div><h2 className="font-display text-2xl font-bold">35 portions are available today.</h2><p className="mt-2 max-w-xl text-sm leading-6 text-white/55">Authorized volunteers can view available surplus and coordinate pickup directly with the canteen team.</p></div><button onClick={() => toast('Authorized volunteers have been notified')} className="btn shrink-0 bg-[#a6e7b6] text-[#173328] hover:bg-white"><Bell size={16} /> Notify volunteers</button></div></Card><div className="grid gap-5 md:grid-cols-2 xl:grid-cols-3">{data.map((item) => <Card key={item.id} hover className="p-5"><div className="flex items-start justify-between"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#e4f5e8] text-[#168653]"><Utensils size={18} /></div><Badge tone={item.status === 'Available' ? 'green' : item.status === 'Reserved' ? 'yellow' : 'gray'}>{item.status}</Badge></div><h3 className="mt-5 font-display font-bold text-[#173328]">{item.food_type}</h3><div className="mt-4 space-y-2 text-xs text-[#7a8c81]"><div className="flex justify-between"><span>Portions</span><b className="text-[#3c5949]">{item.portions}</b></div><div className="flex justify-between"><span>Available</span><b className="text-[#3c5949]">{item.available_time}</b></div><div className="flex justify-between"><span>Location</span><b className="text-right text-[#3c5949]">{item.location}</b></div></div>{item.status === 'Available' && <button onClick={() => update(item.id, 'Reserved')} className="btn btn-secondary mt-5 w-full text-xs">Mark as reserved <ArrowRight size={13} /></button>}</Card>)}</div><div className="mt-6 flex items-start gap-2 rounded-xl border border-[#e1e9e3] bg-white p-4 text-[11px] leading-5 text-[#7e8e85]"><ShieldCheck size={15} className="mt-0.5 shrink-0 text-[#6aa67e]" /><span>Redistribution must follow applicable food-safety guidance and institutional rules. This tool coordinates communication only and does not certify food safety.</span></div>{show && <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#173328]/30 p-5"><Card className="w-full max-w-md p-6"><div className="mb-5 flex items-center justify-between"><div><h3 className="font-display text-lg font-bold text-[#173328]">Create surplus alert</h3><p className="mt-1 text-xs text-[#829289]">Let volunteers know what is available.</p></div><button onClick={() => setShow(false)} className="rounded-lg p-2 text-[#829289] hover:bg-[#f0f5f1]"><X size={18} /></button></div><form onSubmit={submit} className="space-y-4"><div><label className="label">Food type</label><input required className="input" value={form.food_type} onChange={(e) => setForm({ ...form, food_type: e.target.value })} /></div><div className="grid grid-cols-2 gap-3"><div><label className="label">Portions</label><input required min="1" type="number" className="input" value={form.portions} onChange={(e) => setForm({ ...form, portions: e.target.value })} /></div><div><label className="label">Available time</label><input required className="input" value={form.available_time} onChange={(e) => setForm({ ...form, available_time: e.target.value })} /></div></div><div><label className="label">Pickup location</label><input required className="input" value={form.location} onChange={(e) => setForm({ ...form, location: e.target.value })} /></div><div><label className="label">Contact information</label><input required className="input" value={form.contact_info} onChange={(e) => setForm({ ...form, contact_info: e.target.value })} /></div><button disabled={saving} className="btn btn-primary w-full">{saving ? 'Creating…' : 'Create surplus alert'}</button></form></Card></div>}</>; }

function ReportsPage({ data }: { data: DailyFoodData[] }) { const [range, setRange] = useState('Weekly'); const total = data.reduce((s, r) => s + r.meals_consumed, 0); const prepared = data.reduce((s, r) => s + r.meals_prepared, 0); const waste = data.reduce((s, r) => s + Number(r.leftover_kg), 0); return <><div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><SectionTitle eyebrow="Clarity for every decision" title="Reports" description="Export a clean view of the canteen's performance for your next review." /><div className="flex gap-2"><button onClick={() => window.print()} className="btn btn-secondary text-xs"><Printer size={15} /> Print</button><button onClick={() => { const blob = new Blob([`SmartCanteen AI ${range} Report\nMeals prepared: ${prepared}\nMeals consumed: ${total}\nFood waste: ${round(waste,1)} kg`], { type: 'text/plain' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = `smartcanteen-${range.toLowerCase()}-report.txt`; a.click(); URL.revokeObjectURL(url); }} className="btn btn-primary text-xs"><Download size={15} /> Download</button></div></div><div className="mb-5 flex gap-2 rounded-xl bg-[#eaf3ed] p-1">{['Daily','Weekly','Monthly'].map((item) => <button key={item} onClick={() => setRange(item)} className={`flex-1 rounded-lg px-4 py-2 text-xs font-bold ${range === item ? 'bg-white text-[#168653] shadow-sm' : 'text-[#799087]'}`}>{item}</button>)}</div><Card className="overflow-hidden"><div className="border-b border-[#e6eee8] bg-[#fbfdfb] p-6"><div className="flex items-start justify-between"><div><div className="text-[10px] font-bold uppercase tracking-[.15em] text-[#65a67c]">SmartCanteen AI</div><h2 className="mt-2 font-display text-2xl font-bold text-[#173328]">{range} performance report</h2><p className="mt-1 text-xs text-[#829189]">Generated October 24, 2024 · Main campus canteen</p></div><Leaf size={25} className="text-[#7fc293]" /></div></div><div className="grid grid-cols-2 gap-4 p-6 sm:grid-cols-4"><ReportMetric label="Attendance" value="5,184" /><ReportMetric label="Meals prepared" value={prepared.toLocaleString()} /><ReportMetric label="Meals consumed" value={total.toLocaleString()} /><ReportMetric label="Food waste" value={`${round(waste,1)} kg`} /></div><div className="border-t border-[#e6eee8] p-6"><h3 className="font-display font-bold text-[#173328]">Executive summary</h3><p className="mt-3 max-w-3xl text-sm leading-7 text-[#718279]">The canteen maintained strong service levels while reducing avoidable waste. Consumption is tracking below preparation by a healthy buffer, and the AI model recommends keeping tomorrow's production close to the current demand trend.</p><div className="mt-6 grid gap-4 sm:grid-cols-3"><div className="rounded-xl bg-[#f2faf4] p-4"><TrendingDown size={17} className="text-[#168653]" /><div className="mt-3 text-xs text-[#809087]">Waste reduction</div><div className="mt-1 font-display text-xl font-bold text-[#168653]">18.4%</div></div><div className="rounded-xl bg-[#f2faf4] p-4"><CircleDollarSign size={17} className="text-[#168653]" /><div className="mt-3 text-xs text-[#809087]">Estimated savings</div><div className="mt-1 font-display text-xl font-bold text-[#173328]">$2,420</div></div><div className="rounded-xl bg-[#f2faf4] p-4"><BrainCircuit size={17} className="text-[#168653]" /><div className="mt-3 text-xs text-[#809087]">AI predictions</div><div className="mt-1 font-display text-xl font-bold text-[#173328]">91% avg.</div></div></div></div></Card></>; }
function ReportMetric({ label, value }: { label: string; value: string }) { return <div><div className="text-xs text-[#84948b]">{label}</div><div className="mt-2 font-display text-xl font-bold text-[#173328]">{value}</div></div>; }

function AdminPage({ data }: { data: DailyFoodData[] }) { const consumed = data.reduce((s, r) => s + r.meals_consumed, 0); const waste = data.reduce((s, r) => s + Number(r.leftover_kg), 0); const attendance = data.reduce((s, r) => s + r.students_present, 0); return <><SectionTitle eyebrow="Administrator workspace" title="Campus-wide overview" description="A higher-level view of operations, impact and the patterns shaping your campus canteen." /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard icon={Utensils} label="Total meals monitored" value={consumed.toLocaleString()} change="14.2%" /><StatCard icon={Trash2} label="Total food waste" value={`${round(waste, 0)} kg`} change="18.4%" /><StatCard icon={Activity} label="Average waste / day" value={`${round(waste / Math.max(data.length / 4, 1), 1)} kg`} change="6.2%" accent="yellow" /><StatCard icon={CircleDollarSign} label="Estimated savings" value="$14,820" change="22.8%" /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><ChartCard title="Monthly food waste" subtitle="Trend across the current semester"><LineChart values={[24,22,26,20,18,19,17,15,16,13,12,11]} labels={['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']} /></ChartCard><Card className="p-6"><div className="mb-4 flex items-center justify-between"><div><h3 className="font-display font-bold text-[#173328]">AI insights</h3><p className="mt-1 text-xs text-[#83938a]">What the data is telling you</p></div><BrainCircuit size={20} className="text-[#168653]" /></div><div className="space-y-4">{[['Friday is quieter','Lunch consumption is consistently lower on Fridays.'],['Attendance drives waste','Waste increases during low-attendance days.'],['Lunch is predictable','Lunch demand has the lowest forecast variance.']].map(([title, text]) => <div key={title} className="flex gap-3 rounded-xl bg-[#f5faf6] p-3"><div className="mt-0.5 text-[#168653]"><Sparkles size={15} /></div><div><div className="text-xs font-bold text-[#3b5647]">{title}</div><div className="mt-1 text-[11px] leading-5 text-[#809087]">{text}</div></div></div>)}</div></Card></div><Card className="mt-5 p-6"><div className="mb-5 flex items-center justify-between"><div><h3 className="font-display font-bold text-[#173328]">Attendance vs consumption</h3><p className="mt-1 text-xs text-[#83938a]">The relationship across {data.length} tracked meal services</p></div><Badge tone="green"><Activity size={12} /> Live data</Badge></div><div className="grid grid-cols-2 gap-4 sm:grid-cols-4"><div><div className="text-xs text-[#83938a]">Students present</div><div className="mt-2 font-display text-xl font-bold text-[#173328]">{attendance.toLocaleString()}</div></div><div><div className="text-xs text-[#83938a]">Consumption rate</div><div className="mt-2 font-display text-xl font-bold text-[#168653]">86.8%</div></div><div><div className="text-xs text-[#83938a]">Forecast accuracy</div><div className="mt-2 font-display text-xl font-bold text-[#173328]">91.2%</div></div><div><div className="text-xs text-[#83938a]">Reduction target</div><div className="mt-2 font-display text-xl font-bold text-[#168653]">25%</div></div></div></Card></>; }

function SettingsPage({ user }: { user: User }) { return <><SectionTitle eyebrow="Workspace preferences" title="Settings" description="Manage your workspace preferences and notification behavior." /><div className="grid max-w-3xl gap-5"><Card className="p-6"><div className="mb-6 flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#e4f5e8] text-[#168653]"><Users size={19} /></div><div><h3 className="font-display font-bold text-[#173328]">Workspace profile</h3><p className="text-xs text-[#819087]">Your canteen workspace identity</p></div></div><div className="grid gap-4 sm:grid-cols-2"><div><label className="label">Workspace name</label><input className="input" defaultValue="Main Campus Canteen" /></div><div><label className="label">Account email</label><input className="input" defaultValue={user.email} readOnly /></div></div><button className="btn btn-primary mt-5" onClick={() => alert('Workspace settings saved')}>Save changes</button></Card><Card className="p-6"><div className="mb-5 flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#fff4d7] text-[#c48e25]"><Bell size={19} /></div><div><h3 className="font-display font-bold text-[#173328]">Notifications</h3><p className="text-xs text-[#819087]">Choose what your team hears about</p></div></div>{['High waste alerts','Daily prediction summaries','Surplus volunteer notifications'].map((label, i) => <label key={label} className="flex items-center justify-between border-b border-[#edf2ee] py-4 last:border-0"><span className="text-sm font-semibold text-[#496151]">{label}</span><input type="checkbox" defaultChecked={i !== 1} className="h-4 w-4 accent-[#168653]" /></label>)}</Card></div></>; }

function App() { const [user, setUser] = useState<User | null>(() => getStoredUser()); const [showLogin, setShowLogin] = useState(false); const [view, setView] = useState<View>('dashboard'); const [toastMessage, setToastMessage] = useState(''); const daily = useDailyData(); const surplus = useSurplus(); const closeToast = () => setToastMessage(''); const toast = (message: string) => { setToastMessage(message); window.setTimeout(closeToast, 3500); }; if (!user) return showLogin ? <Login onLogin={(nextUser) => { setUser(nextUser); setShowLogin(false); }} onBack={() => setShowLogin(false)} /> : <Landing onStart={() => setShowLogin(true)} />; return <><Shell user={user} view={view} onView={setView} onLogout={() => { signOutDemo(); setUser(null); setView('dashboard'); }}><>{view === 'dashboard' && <Dashboard data={daily.data} onView={setView} />}{view === 'daily' && <DailyPage data={daily.data} onSaved={() => void daily.refresh()} toast={toast} />}{view === 'prediction' && <PredictionPage data={daily.data} toast={toast} />}{view === 'waste' && <WastePage data={daily.data} />}{view === 'surplus' && <SurplusPage data={surplus.data} onRefresh={() => void surplus.refresh()} toast={toast} />}{view === 'reports' && <ReportsPage data={daily.data} />}{view === 'settings' && <SettingsPage user={user} />}{view === 'admin' && user.role === 'admin' && <AdminPage data={daily.data} />}</></Shell>{toastMessage && <Toast message={toastMessage} onClose={closeToast} />}</>; }

export default App;
